<?php require 'auth.php';require '../includes/config.php';$id=(int)($_GET['id']??0);$q=$conn->prepare("SELECT * FROM properties WHERE id=?");$q->bind_param("i",$id);$q->execute();$p=$q->get_result()->fetch_assoc();if(!$p)die("Property not found");
if($_SERVER['REQUEST_METHOD']==='POST'){$s=$conn->prepare("UPDATE properties SET title=?,description=?,type=?,listing_type=?,city=?,address=?,price=?,area=?,bedrooms=?,bathrooms=?,parking=?,image=? WHERE id=?");$s->bind_param("ssssssdiiiisi",$_POST['title'],$_POST['description'],$_POST['type'],$_POST['listing_type'],$_POST['city'],$_POST['address'],$_POST['price'],$_POST['area'],$_POST['bedrooms'],$_POST['bathrooms'],$_POST['parking'],$_POST['image'],$id);$s->execute();header("Location: properties.php");exit;}
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Edit Property</title><link rel="stylesheet" href="../css/style.css"></head><body><?php include 'header.php';?><section class="pagehero"><div class="container"><h1>Edit Property</h1><p>Update property information.</p></div></section><section class="section"><div class="container" style="max-width:900px"><form class="form-card" method="post"><div class="formgrid"><div class="full"><label>Title</label><input name="title" value="<?=htmlspecialchars($p['title'])?>" required></div><div><label>Type</label><select name="type"><?php foreach(['House','Apartment','Villa','Commercial','Plot'] as $x)echo "<option ".($p['type']===$x?'selected':'').">$x</option>";?></select></div><div><label>Listing</label><select name="listing_type"><option <?=$p['listing_type']==='Buy'?'selected':''?>>Buy</option><option <?=$p['listing_type']==='Rent'?'selected':''?>>Rent</option></select></div><div><label>City</label><input name="city" value="<?=htmlspecialchars($p['city'])?>"></div><div><label>Address</label><input name="address" value="<?=htmlspecialchars($p['address'])?>"></div><div><label>Price</label><input type="number" step=".01" name="price" value="<?=$p['price']?>"></div><div><label>Area</label><input type="number" name="area" value="<?=$p['area']?>"></div><div><label>Bedrooms</label><input type="number" name="bedrooms" value="<?=$p['bedrooms']?>"></div><div><label>Bathrooms</label><input type="number" name="bathrooms" value="<?=$p['bathrooms']?>"></div><div><label>Parking</label><input type="number" name="parking" value="<?=$p['parking']?>"></div><div class="full"><label>Image URL</label><input name="image" value="<?=htmlspecialchars($p['image'])?>"></div><div class="full"><label>Description</label><textarea name="description" rows="5"><?=htmlspecialchars($p['description'])?></textarea></div><div class="full"><button class="btn gold">Update Property</button></div></div></form></div></section><?php echo '<footer><div class="container"><div class="copyright">© 2026 DreamNest Admin Panel</div></div></footer>';?></body></html>